16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
64	    private Set<Pet> pets;
65	
66	    public String getAddress() {
67	        return this.address;
68	    }
69	
70	    public void setAddress(String address) {
71	        this.address = address;
72	    }
73	
74	    public String getCity() {
75	        return this.city;
76	    }
77	
78	    public void setCity(String city) {
79	        this.city = city;
80	    }
81	
82	    public String getTelephone() {
83	        return this.telephone;
84	    }
85	
86	    public void setTelephone(String telephone) {
87	        this.telephone = telephone;
88	    }
89	
90	    public String getEmail() {
91	        return this.email;
92	    }
93	
94	    public void setEmail(String email) {
95	        this.email = email;
96	    }
97	
98	    public LocalDate getRegistrationDate() {
99	        return this.registrationDate;
100	    }
101	
102	    public void setRegistrationDate(LocalDate registrationDate) {
103	        this.registrationDate = registrationDate;
104	    }
105	
106	    public String getCustomerCode() {
107	        return this.customerCode;
108	    }
109	
110	    public void setCustomerCode(String customerCode) {
111	        this.customerCode = customerCode;
112	    }
113	
114	    public String getHouseholdId() {
115	        return this.householdId;
116	    }
117	
118	    public void setHouseholdId(String householdId) {
119	        this.householdId = householdId;
120	    }
121	
122	    /**
123	     * The owner's name formatted as {@code "LastName, FirstName"} from the stored names.
124	     *
125	     * @return the formatted display name
126	     */
127	    public String getDisplayName() {
128	        return this.getLastName() + ", " + this.getFirstName();
129	    }
130	
131	    /**
132	     * The owner's initials: the upper-cased first letters of the first and last
133	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
134	     *
135	     * @return the formatted initials
136	     */
137	    public String getInitials() {
138	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
139	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
140	    }
141	
142	    protected Set<Pet> getPetsInternal() {
143	        if (this.pets == null) {
144	            this.pets = new HashSet<>();
145	        }
146	        return this.pets;
147	    }
148	
149	    protected void setPetsInternal(Set<Pet> pets) {
150	        this.pets = pets;
151	    }
152	
153	    public List<Pet> getPets() {
154	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
155	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
156	        return Collections.unmodifiableList(sortedPets);
157	    }
158	
159	    public void setPets(List<Pet> pets) {
160	        this.pets = new HashSet<>(pets);
161	    }
162	
163	    public void addPet(Pet pet) {
164	        getPetsInternal().add(pet);
165	        pet.setOwner(this);
166	    }
167	
168	    /**
169	     * Return the Pet with the given name, or null if none found for this Owner.
170	     *
171	     * @param name to test
172	     * @return true if pet name is already in use
173	     */
174	    public Pet getPet(String name) {
175	        return getPet(name, false);
176	    }
177	
178	    /**
179	     * Return the Pet with the given name, or null if none found for this Owner.
180	     *
181	     * @param name to test
182	     * @return true if pet name is already in use
183	     */
184	    public Pet getPet(String name, boolean ignoreNew) {
185	        name = name.toLowerCase();
186	        for (Pet pet : getPetsInternal()) {
187	            if (!ignoreNew || !pet.isNew()) {
188	                String compName = pet.getName();
189	                compName = compName.toLowerCase();
190	                if (compName.equals(name)) {
191	                    return pet;
192	                }
193	            }
194	        }
195	        return null;
196	    }
197	
198	    public Pet getPet(Integer petId) {
199	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
200	    }
201	
202	    @Override
203	    public String toString() {
204	        return new ToStringCreator(this)
205	
206	            .append("id", this.getId())
207	            .append("new", this.isNew())
208	            .append("lastName", this.getLastName())
209	            .append("firstName", this.getFirstName())
210	            .append("address", this.address)
211	            .append("city", this.city)
212	            .append("telephone", this.telephone)
213	            .append("email", this.email)
214	            .toString();
215	    }
216	}
