17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.nio.charset.StandardCharsets;
20	import java.security.MessageDigest;
21	import java.time.LocalDate;
22	import java.util.Collection;
23	import java.util.List;
24	import java.util.Locale;
25	import java.util.Objects;
26	import java.util.regex.Pattern;
27	
28	import org.springframework.http.HttpHeaders;
29	import org.springframework.http.HttpStatus;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.mapper.OwnerMapper;
32	import org.springframework.samples.petclinic.mapper.PetMapper;
33	import org.springframework.samples.petclinic.mapper.VisitMapper;
34	import org.springframework.samples.petclinic.model.Owner;
35	import org.springframework.samples.petclinic.model.Pet;
36	import org.springframework.samples.petclinic.model.Visit;
37	import org.springframework.samples.petclinic.rest.api.OwnersApi;
38	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
39	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
40	import org.springframework.samples.petclinic.rest.dto.PetDto;
41	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
42	import org.springframework.samples.petclinic.rest.dto.VisitDto;
43	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
44	import org.springframework.samples.petclinic.service.ClinicService;
45	import org.springframework.security.access.prepost.PreAuthorize;
46	import org.springframework.web.bind.annotation.CrossOrigin;
47	import org.springframework.web.bind.annotation.RequestMapping;
48	import org.springframework.web.bind.annotation.RestController;
49	import org.springframework.web.util.UriComponentsBuilder;
50	
51	import jakarta.transaction.Transactional;
52	
53	/**
54	 * @author Vitaliy Fedoriv
55	 */
56	
57	@RestController
58	@CrossOrigin(exposedHeaders = "errors, content-type")
59	@RequestMapping("/api")
60	public class OwnerRestControllerV1 implements OwnersApi {
61	
62	    /**
63	     * Pattern for a syntactically valid email address: a non-empty local part, an '@', and a
64	     * dotted domain ending in a letters-only label. Applied to the trimmed, lower-cased value.
65	     */
66	    private static final Pattern EMAIL_PATTERN =
67	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
68	
69	    private final ClinicService clinicService;
70	
71	    private final OwnerMapper ownerMapper;
72	
73	    private final PetMapper petMapper;
74	
75	    private final VisitMapper visitMapper;
76	
77	    public OwnerRestControllerV1(ClinicService clinicService,
78	                                 OwnerMapper ownerMapper,
79	                                 PetMapper petMapper,
80	                                 VisitMapper visitMapper) {
81	        this.clinicService = clinicService;
82	        this.ownerMapper = ownerMapper;
83	        this.petMapper = petMapper;
84	        this.visitMapper = visitMapper;
85	    }
86	
87	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
88	    @Override
89	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
90	        Collection<Owner> owners;
91	        if (lastName != null) {
92	            owners = this.clinicService.findOwnerByLastName(lastName);
93	        } else {
94	            owners = this.clinicService.findAllOwners();
95	        }
96	        if (owners.isEmpty()) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
105	        Owner owner = this.clinicService.findOwnerById(ownerId);
106	        if (owner == null) {
107	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
108	        }
109	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
115	        HttpHeaders headers = new HttpHeaders();
116	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
117	        String telephone = toE164(owner.getTelephone());
118	        if (telephone == null) {
119	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
120	        }
121	        owner.setTelephone(telephone);
122	        if (owner.getRegistrationDate() == null) {
123	            owner.setRegistrationDate(LocalDate.now());
124	        }
125	        if (owner.getEmail() != null) {
126	            String email = normalizeEmail(owner.getEmail());
127	            if (!EMAIL_PATTERN.matcher(email).matches()) {
128	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
129	            }
130	            owner.setEmail(email);
131	        }
132	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
133	            .anyMatch(existing -> telephone.equals(toE164(existing.getTelephone())));
134	        if (telephoneInUse) {
135	            return new ResponseEntity<>(HttpStatus.CONFLICT);
136	        }
137	        String lastNameKey = householdKey(owner.getLastName());
138	        String addressKey = householdKey(owner.getAddress());
139	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
140	            .filter(existing -> lastNameKey.equals(householdKey(existing.getLastName()))
141	                && addressKey.equals(householdKey(existing.getAddress())))
142	            .toList();
143	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
144	            String householdId = householdMembers.stream()
145	                .map(Owner::getHouseholdId)
146	                .filter(Objects::nonNull)
147	                .findFirst()
148	                .orElseGet(() -> householdId(owner));
149	            owner.setHouseholdId(householdId);
150	            for (Owner member : householdMembers) {
151	                if (member.getHouseholdId() == null) {
152	                    member.setHouseholdId(householdId);
153	                    this.clinicService.saveOwner(member);
154	                }
155	            }
156	        } else if (!householdMembers.isEmpty()) {
157	            return new ResponseEntity<>(HttpStatus.CONFLICT);
158	        }
159	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
160	        this.clinicService.saveOwner(owner);
161	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
162	        headers.setLocation(UriComponentsBuilder.newInstance()
163	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
164	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
165	    }
166	
167	    /**
168	     * Normalizes a telephone number into E.164 form. Spaces, dashes and brackets are stripped.
169	     * When the value carries a leading {@code '+'} its country code is kept as given; otherwise the
170	     * Australian country code {@code '+61'} is assumed and a single leading {@code '0'} is dropped
171	     * from the national digits. The result must carry 8 to 15 digits after the {@code '+'}.
172	     *
173	     * @param telephone the raw telephone value (may be {@code null})
174	     * @return the E.164 telephone (e.g. {@code "+61412345678"}), or {@code null} if it cannot form
175	     *         a valid E.164 number
176	     */
177	    private String toE164(String telephone) {
178	        if (telephone == null) {
179	            return null;
180	        }
181	        String trimmed = telephone.trim();
182	        boolean hasCountryCode = trimmed.startsWith("+");
183	        String cleaned = trimmed.replaceAll("[\\s()\\[\\]-]", "");
184	        if (hasCountryCode) {
185	            cleaned = cleaned.substring(1);
186	        }
187	        if (!cleaned.matches("[0-9]+")) {
188	            return null;
189	        }
190	        String digits;
191	        if (hasCountryCode) {
192	            digits = cleaned;
193	        } else {
194	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
195	            digits = "61" + national;
196	        }
197	        if (digits.length() < 8 || digits.length() > 15) {
198	            return null;
199	        }
200	        return "+" + digits;
201	    }
202	
203	    /**
204	     * Normalizes an email address for storage by trimming surrounding whitespace and lower-casing
205	     * it. The result is validated by the caller against {@link #EMAIL_PATTERN}.
206	     *
207	     * @param email the raw email value (must not be {@code null})
208	     * @return the trimmed, lower-cased email
209	     */
210	    private String normalizeEmail(String email) {
211	        return email.trim().toLowerCase(Locale.ROOT);
212	    }
213	
214	    /**
215	     * Normalizes a value for household-duplicate comparison: surrounding whitespace is trimmed,
216	     * internal runs of whitespace are collapsed to a single space and the result is lower-cased,
217	     * so that owners are compared case-insensitively with collapsed whitespace.
218	     *
219	     * @param value the raw value (must not be {@code null})
220	     * @return the normalized comparison key
221	     */
222	    private String householdKey(String value) {
223	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
224	    }
225	
226	    /**
227	     * Derives a stable, shared household identifier for the owner's household. The value is a
228	     * deterministic function of the normalized last name and address ({@link #householdKey}), so
229	     * every owner in the same household derives the identical identifier of the form
230	     * {@code 'HH-<12 upper-case hex>'}.
231	     *
232	     * @param owner the owner whose household identifier is derived
233	     * @return the stable household identifier
234	     */
235	    private String householdId(Owner owner) {
236	        String key = householdKey(owner.getLastName()) + "|" + householdKey(owner.getAddress());
237	        try {
238	            byte[] digest = MessageDigest.getInstance("SHA-256")
239	                .digest(key.getBytes(StandardCharsets.UTF_8));
240	            StringBuilder sb = new StringBuilder(digest.length * 2);
241	            for (byte b : digest) {
242	                sb.append(String.format("%02x", b));
243	            }
244	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
245	        }
246	        catch (java.security.NoSuchAlgorithmException e) {
247	            throw new IllegalStateException("SHA-256 not available", e);
248	        }
249	    }
250	
251	    /**
252	     * Builds the customer code for a newly registered owner in the form
253	     * {@code '<LAST3>-<NNNN>'}, where {@code LAST3} is the upper-cased first three letters
254	     * of the last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to
255	     * one more than the current number of owners (e.g. {@code 'SMI-0007'}).
256	     *
257	     * @param lastName the owner's last name
258	     * @return the assigned customer code
259	     */
260	    private String nextCustomerCode(String lastName) {
261	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
262	        int sequence = this.clinicService.findAllOwners().size() + 1;
263	        return String.format(Locale.ROOT, "%s-%04d", last3, sequence);
264	    }
265	
266	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
267	    @Override
268	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
269	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
270	        if (currentOwner == null) {
271	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
272	        }
273	        String email = ownerFieldsDto.getEmail();
274	        if (email != null) {
275	            email = normalizeEmail(email);
276	            if (!EMAIL_PATTERN.matcher(email).matches()) {
